// AtlasForge service worker — generated by tools/build.mjs from tools/sw.template.js.
// Do not edit sw.js by hand.
//
// shell  — the app itself (HTML, CSS, JS, vendor libs, icons): precached on install,
//          served cache-first (every URL carries a content hash, so it never goes stale).
// data   — basemap GeoJSON (data/*.geojson, ~100 MB in total): cached the first time a
//          template is opened (or via "download for offline"), then served cache-first.
// A new version installs in the background and waits; the page asks the user to reload
// (message "skipWaiting") so an edit in progress is never interrupted.
const VERSION = "__VERSION__";
const SHELL = "af-shell-" + VERSION;
const DATA = "af-data-v1";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(SHELL).then((c) => c.addAll(PRECACHE)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith("af-shell-") && k !== SHELL).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  if (event.data === "skipWaiting") self.skipWaiting();
});

function isData(url) {
  return /\/data\/[^/]+\.(geo)?json$/.test(url.pathname);
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // the page itself: network first (quick updates), cached shell when offline
  if (req.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 4000);
        const res = await fetch(req, { signal: ctrl.signal });
        clearTimeout(timer);
        return res;
      } catch (e) {
        const cache = await caches.open(SHELL);
        return (await cache.match(req, { ignoreSearch: true })) || (await cache.match("./")) || Response.error();
      }
    })());
    return;
  }

  if (isData(url)) {
    event.respondWith((async () => {
      const cache = await caches.open(DATA);
      const hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req);
    return hit || fetch(req);
  })());
});
